// LinkedIn — All O(1) data structure (LeetCode 432): Inc, Dec, GetMaxKey, GetMinKey, all O(1).
// Buckets of keys by count, kept in a doubly linked list in ascending count order.
public sealed class AllOne {
    sealed class Bucket { public int Count; public readonly HashSet<string> Keys = new(); }
    readonly LinkedList<Bucket> _buckets = new();                       // ascending by Count
    readonly Dictionary<string, LinkedListNode<Bucket>> _where = new();
    readonly object _gate = new();

    public void Inc(string key) {
        lock (_gate) {
            if (_where.TryGetValue(key, out var node)) {
                var next = node.Next;
                if (next == null || next.Value.Count != node.Value.Count + 1)
                    next = _buckets.AddAfter(node, new Bucket { Count = node.Value.Count + 1 });
                next.Value.Keys.Add(key); _where[key] = next;
                Detach(node, key);
            } else {
                var first = _buckets.First;
                if (first == null || first.Value.Count != 1) first = _buckets.AddFirst(new Bucket { Count = 1 });
                first.Value.Keys.Add(key); _where[key] = first;
            }
        }
    }

    public void Dec(string key) {
        lock (_gate) {
            if (!_where.TryGetValue(key, out var node)) return;     // decrementing an absent key: no-op
            if (node.Value.Count == 1) { _where.Remove(key); Detach(node, key); return; }
            var prev = node.Previous;
            if (prev == null || prev.Value.Count != node.Value.Count - 1)
                prev = _buckets.AddBefore(node, new Bucket { Count = node.Value.Count - 1 });
            prev.Value.Keys.Add(key); _where[key] = prev;
            Detach(node, key);
        }
    }

    public string GetMaxKey() { lock (_gate) return _buckets.Last == null ? "" : Any(_buckets.Last.Value.Keys); }
    public string GetMinKey() { lock (_gate) return _buckets.First == null ? "" : Any(_buckets.First.Value.Keys); }

    void Detach(LinkedListNode<Bucket> node, string key) {
        node.Value.Keys.Remove(key);
        if (node.Value.Keys.Count == 0) _buckets.Remove(node);
    }
    static string Any(HashSet<string> keys) { foreach (var k in keys) return k; return ""; }
}
